local CommendationScroll = {}
local PRODUCTS = {
    simple_parchment_commendation = { name = "Preprosta pergamentna omemba", parchmentCost = 2, inkCost = 1, time = 4, cost = 90, happiness = 1, prestige = 2, description = "Preprosta omemba za služenje." },
    illuminated_praise_scroll = { name = "Iluminirani sprehvalni zvitek", parchmentCost = 3, inkCost = 1, goldCost = 1, time = 7, cost = 280, happiness = 2, prestige = 5, description = "Iluminirani zvitek za civilne zasluge." },
    silver_sealed_decree = { name = "Srebrnopesačani odlok", parchmentCost = 3, inkCost = 1, silverCost = 1, goldCost = 1, time = 11, cost = 720, happiness = 3, prestige = 11, description = "Odlok s srebrnim pečatom za plemiče." },
    gilded_honor_patent = { name = "Pozlačeni častni patent", parchmentCost = 4, inkCost = 1, goldCost = 2, silverCost = 1, time = 15, cost = 1700, happiness = 4, prestige = 22, description = "Patent z zlatim pečatom za visoke časti." },
    jewel_set_royal_letter = { name = "Draguljasta kraljeva listina", parchmentCost = 4, inkCost = 1, goldCost = 2, jewelCost = 1, time = 19, cost = 3700, happiness = 6, prestige = 38, description = "Listina z draguljnim pečatom za suverene časti." },
    sovereign_grand_diploma = { name = "Suvereni veliki diplom", parchmentCost = 6, inkCost = 2, goldCost = 3, silverCost = 2, jewelCost = 2, pearlCost = 2, time = 26, cost = 8000, happiness = 12, prestige = 72, description = "Veliki suvereni diplom z biseri za krono." },
}
local BUILDINGS = {
    scroll_scriptorium = { name = "Zvitočno skriptorij", cost = { gold = 280, wood = 160, stone = 100, parchment = 4 }, upkeep = 5, qualityBonus = 5 },
    honor_chancery = { name = "Častna pisarna", cost = { gold = 1000, wood = 320, stone = 220, silver = 6, parchment = 6 }, upkeep = 22, qualityBonus = 18 },
    master_charters_atelier = { name = "Mojstrski listinarski atelje", cost = { gold = 2800, wood = 380, stone = 460, silver = 32, gold = 6 }, upkeep = 64, qualityBonus = 30 },
    sovereign_chancery_palace = { name = "Suverena listinarska palača", cost = { gold = 12000, wood = 600, stone = 800, gold = 80, jewel = 18 }, upkeep = 240, qualityBonus = 55, prestigeBonus = 50 },
}
CommendationScroll.parchmentStock = 24; CommendationScroll.inkStock = 18; CommendationScroll.silverStock = 8; CommendationScroll.goldStock = 6; CommendationScroll.jewelStock = 4; CommendationScroll.pearlStock = 4
CommendationScroll.productStock = {}; CommendationScroll.buildings = {}; CommendationScroll.maker = nil; CommendationScroll.activeMaking = {}; CommendationScroll.totalProducts = 0; CommendationScroll.dayTimer = 0
function CommendationScroll.init() CommendationScroll.parchmentStock=24; CommendationScroll.inkStock=18; CommendationScroll.silverStock=8; CommendationScroll.goldStock=6; CommendationScroll.jewelStock=4; CommendationScroll.pearlStock=4; CommendationScroll.productStock={}; CommendationScroll.buildings={}; CommendationScroll.maker=nil; CommendationScroll.activeMaking={}; CommendationScroll.totalProducts=0; CommendationScroll.dayTimer=0; print("[CommendationScroll] Royal Commendation Scroll System initialized (6 products, 4 buildings)") end
function CommendationScroll.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; CommendationScroll.maker={name=n or ("Listinar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Listinar najet: %s (spretnost: %d)",CommendationScroll.maker.name,s),"success") end; return true end
function CommendationScroll.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function CommendationScroll.build(id) local ok,e=CommendationScroll.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(CommendationScroll.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function CommendationScroll.getQualityBonus() local b=0; for _,bd in ipairs(CommendationScroll.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function CommendationScroll.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.parchmentCost and CommendationScroll.parchmentStock<(d.parchmentCost or 0) then return false,"Premalo pergamenta" end; if d.inkCost and CommendationScroll.inkStock<(d.inkCost or 0) then return false,"Premalo črnila" end; if d.silverCost and CommendationScroll.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and CommendationScroll.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and CommendationScroll.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and CommendationScroll.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #CommendationScroll.buildings==0 then return false,"Potreben zvitočni skriptorij" end; if not CommendationScroll.maker then return false,"Potreben listinar" end; return true end
function CommendationScroll.make(pt,qty) qty=qty or 1; local ok,e=CommendationScroll.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.parchmentCost then CommendationScroll.parchmentStock=CommendationScroll.parchmentStock-d.parchmentCost*qty end; if d.inkCost then CommendationScroll.inkStock=CommendationScroll.inkStock-d.inkCost*qty end; if d.silverCost then CommendationScroll.silverStock=CommendationScroll.silverStock-d.silverCost*qty end; if d.goldCost then CommendationScroll.goldStock=CommendationScroll.goldStock-d.goldCost*qty end; if d.jewelCost then CommendationScroll.jewelStock=CommendationScroll.jewelStock-d.jewelCost*qty end; if d.pearlCost then CommendationScroll.pearlStock=CommendationScroll.pearlStock-d.pearlCost*qty end; local t=d.time; if CommendationScroll.maker then t=math.max(1,t-math.floor(CommendationScroll.maker.skill/13)) end; table.insert(CommendationScroll.activeMaking,{id="commendation_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function CommendationScroll.completeMaking(m) local q=1.0+(CommendationScroll.getQualityBonus()/100); if CommendationScroll.maker then q=q+(CommendationScroll.maker.skill/140) end; q=math.min(2.5,q); CommendationScroll.productStock[m.productType]=(CommendationScroll.productStock[m.productType] or 0)+m.quantity; CommendationScroll.totalProducts=CommendationScroll.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if CommendationScroll.maker then CommendationScroll.maker.itemsMade=CommendationScroll.maker.itemsMade+m.quantity; if math.random()<0.25 then CommendationScroll.maker.skill=math.min(100,CommendationScroll.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Listina izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"commendation.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function CommendationScroll.update(dt) if not _G.state then return end; CommendationScroll.dayTimer=CommendationScroll.dayTimer+dt; if CommendationScroll.dayTimer>=30 then CommendationScroll.dayTimer=0; for i=#CommendationScroll.activeMaking,1,-1 do local m=CommendationScroll.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then CommendationScroll.completeMaking(m); table.remove(CommendationScroll.activeMaking,i) end end; local tu=0; for _,bd in ipairs(CommendationScroll.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if CommendationScroll.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function CommendationScroll.getStats() return {parchmentStock=CommendationScroll.parchmentStock,inkStock=CommendationScroll.inkStock,silverStock=CommendationScroll.silverStock,goldStock=CommendationScroll.goldStock,jewelStock=CommendationScroll.jewelStock,pearlStock=CommendationScroll.pearlStock,productStock=CommendationScroll.productStock,numBuildings=#CommendationScroll.buildings,hasMaker=CommendationScroll.maker~=nil,makerName=CommendationScroll.maker and CommendationScroll.maker.name or "—",makerSkill=CommendationScroll.maker and CommendationScroll.maker.skill or 0,activeMaking=#CommendationScroll.activeMaking,totalProducts=CommendationScroll.totalProducts} end
return CommendationScroll
